    checkCurrentWindow();
    double[][] tempret = new double[dets.length][];
    for (int k = 0; k  tempret.length; k++) {
        tempret[k] = getPairwiseFlowImpl(dets[k][0], dets[k][1]);
    }
    return tempret;
}

