public static Object[] appendToArray(Object[] original, Object item) {
    Object[] retVal = new Object[original.length + 1];
    for (int i = 0; i  original.length; i++) {
        retVal[i] = original[i];
    }
    retVal[retVal.length - 1] = item;
    return retVal;
}

