    if (stream == null) {
        throw new IllegalArgumentException("Argument must not be null");
    }
    int[] binaryGuid = new int[GUID.GUID_LENGTH];
    for (int i = 0; i  binaryGuid.length; i++) {
        binaryGuid[i] = stream.read();
    }
    return new GUID(binaryGuid);
}

