public void fit() throws CalibrationFitException {
    final double[] sqrtE = new double[ptsEnergy.length];
    for (int i = 0; i  ptsEnergy.length; i++) {
        sqrtE[i] = Math.sqrt(ptsEnergy[i]);
    }
    setCoeff(linearRegression(ptsChannel, sqrtE));
}

