public static byte[] getByteList(byte bits) {
    byte[] b = new byte[Byte.SIZE];
    for (int i = 0; i  Byte.SIZE; i++) {
        b[i] = (byte) (bits  (Byte.SIZE - 1 - i)  0x01);
    }
    return b;
}

