public static double[] subtract(final double[] aa, final double[] bb, final double[] cc) {
    if (aa.length != bb.length) throw new RuntimeException("Vectors must have same length.\n");
    for (int ii = 0; ii  aa.length; ii++) {
        cc[ii] = bb[ii] - aa[ii];
    }
    return cc;
}

