private Index[] loadIndexes() {
    String[] indexStrings = { "1-byte character\toN7/\tq", "reclassify\ty3Me\t4", "watch-dog\t14nk\tBx", "zymotic\toN2l\tBJ", "decorously\tuSf3\t4", "Forecast error\tqnR8\tDC", "procrastinating\tahbX\tBN", "two-master\tk+2K\tBU", "voidable\tm0Yz\tBa", "Z-score\tsmpF\tm" };
    IndexParser parser = IndexParsers.newParser();
    Index[] result = new Index[indexStrings.length];
    for (int item = 0; item  indexStrings.length; item++) {
        result[item] = parser.parse(indexStrings[item]);
    }
    return result;
}

