public static final F, T T[] transform(F[] src, FunctionF, T f, ClassT clazz) {
    T[] dest = (T[]) Array.newInstance(clazz, src.length);
    for (int i = 0; i  src.length; i++) {
        dest[i] = f.apply(src[i]);
    }
    return dest;
}

